part of 'app.dart';
extension BuildingUI on _WorkspaceState {
 Widget buildingView()=>FutureBuilder<dynamic>(future:api.request('/invites'),builder:(context,snap){
 final invites=(snap.data as List? ?? []);
 return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[text('A home for every neighbour.',size:28,weight:FontWeight.w700),const SizedBox(height:8),text('One invitation per apartment. Revoke access to an invite at any time.',color:muted),const SizedBox(height:22),Wrap(spacing:12,runSpacing:12,children:[button('Create a building',()=>createBuilding()),button('Generate apartment invite',()=>generateInvite())]),const SizedBox(height:24),if(snap.hasError)text('${snap.error}',color:Colors.red),...invites.map((i)=>Padding(padding:const EdgeInsets.only(bottom:8),child:card(Row(children:[const Icon(Icons.key,color:blue),const SizedBox(width:18),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[text('Apartment ${i['apartment']}',weight:FontWeight.w700),SelectableText(i['code'],style:const TextStyle(color:muted,fontSize:12))])),if(i['revoked']==true)text('Revoked',color:Colors.red)else TextButton(onPressed:()=>action(()async{await api.request('/invites/${i['code']}/revoke',method:'POST',body:{});setState((){});}),child:const Text('Revoke'))]))))]);});
 Future<void> generateInvite()async{final apt=TextEditingController();await showDialog<void>(context:context,builder:(c)=>AlertDialog(title:const Text('Generate a new invitation'),content:SizedBox(width:340,child:Column(mainAxisSize:MainAxisSize.min,children:[field(apt,'Apartment number'),text('The previous invite for this apartment will be revoked.',color:muted)])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),TextButton(onPressed:(){Navigator.pop(c);action(()async{await api.request('/invites',method:'POST',body:{'apartment':int.tryParse(apt.text)??0});});},child:const Text('Generate'))]));}
 Future<void> createBuilding()async{final title=TextEditingController(),address=TextEditingController(),apts=TextEditingController(text:'120'),entrances=TextEditingController(text:'3'),floors=TextEditingController(text:'9');await showDialog<void>(context:context,builder:(c)=>AlertDialog(title:const Text('Create a building'),content:SizedBox(width:420,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[field(title,'Building name'),field(address,'Address'),field(apts,'Apartments'),field(entrances,'Entrances'),field(floors,'Floors')]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),TextButton(onPressed:(){Navigator.pop(c);action(()async{final b=await api.request('/buildings',method:'POST',body:{'name':title.text,'address':address.text,'apartments':int.tryParse(apts.text)??0,'entrances':int.tryParse(entrances.text)??0,'floors':int.tryParse(floors.text)??0});final u=await api.request('/me');setState((){building=Map<String,dynamic>.from(b);me=Map<String,dynamic>.from(u);});});},child:const Text('Create & generate invites'))]));}
}
